function extractStacktrace(e,offset){offset=offset===undefined?4:offset;var stack,include,i;if(e.stack){stack=e.stack.split("\n");if(/^error$/i.test(stack[0])){stack.shift()}if(fileName){include=[];for(i=offset;i<stack.length;i++){if(stack[i].indexOf(fileName)!==-1){break}include.push(stack[i])}if(include.length){return include.join("\n")}}return stack[offset]}else if(e.sourceURL){if(/qunit.js$/.test(e.sourceURL)){return}return e.sourceURL+":"+e.line}}function sourceFromStacktrace(offset){var error=new Error;if(!error.stack){try{throw error}catch(err){error=err}}return extractStacktrace(error,offset)}